{
  "implementation": "def solve(case):
    segments = case['segments']
    budget = case['budget']
    sum_minima = sum(s['minimum'] for s in segments)
    sum_capacity = sum(s['capacity'] for s in segments)
    if budget < sum_minima or budget > sum_capacity:
        raise ValueError('Budget out of feasible range')
    alloc = {s['name']: s['minimum'] for s in segments}
    remaining = budget - sum_minima
    # For tie-breaking, preserve original order
    order = [s['name'] for s in segments]
    while remaining > 0:
        best_idx = -1
        best_marginal = -1.0
        for i, s in enumerate(segments):
            name = s['name']
            if alloc[name] >= s['capacity']:
                continue
            marginal = s['importance'] / (alloc[name] + 1)
            if marginal > best_marginal:
                best_marginal = marginal
                best_idx = i
            elif marginal == best_marginal and best_idx == -1:
                # keep first encountered (tie by order)
                pass
        if best_idx == -1:
            # Should not happen due to capacity check
            break
        name = segments[best_idx]['name']
        alloc[name] += 1
        remaining -= 1
    return {
        'allocations': alloc,
        'segment_order': order,
        'total_allocated': sum(alloc.values())
    }"
}
